// Validates the form and builds the request for Google's Gemini API.
const CONFIG = {
  MODEL: 'gemini-2.5-flash',        // any Gemini text model that supports generateContent, e.g. a newer "flash" model
  LANGUAGE: 'the same language as the title and keywords', // e.g. 'English'
  BRAND_VOICE: 'friendly, clear and professional, never pushy', // describe your voice in one line
};

const f = $json || {};
const title = String(f['Post Title'] || '').trim();
const topic = String(f['Keywords / Topic'] || '').trim();
const link = String(f['Link'] || '').trim();
const imageUrl = String(f['Image URL'] || '').trim();
const clientId = String(f['Client workspace ID'] || '').trim();
const isHttp = (u) => /^https?:\/\/[^\s]+$/i.test(u);
if (!title || !topic) throw new Error('Post Title and Keywords / Topic are required.');
if (link && !isHttp(link)) throw new Error('Link must start with http:// or https://');
if (imageUrl && !isHttp(imageUrl)) throw new Error('Image URL must start with http:// or https:// and be publicly reachable.');
if (clientId && !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(clientId)) throw new Error('Client workspace ID must be a UUID (see GET https://cekiva.com/api/v1/clients).');

const system = [
  'You are a social media copywriter. Write one post for EACH of these networks from the information the user gives you, in ' + CONFIG.LANGUAGE + '.',
  'Voice: ' + CONFIG.BRAND_VOICE + '.',
  'Rules per network (hard limits include hashtags and emoji):',
  '- facebook: 2-4 short sentences, community tone, one clear call to action.',
  '- instagram: at most 2000 characters, visual storytelling, a few emoji, 5-8 relevant hashtags at the end. Do not write a link: captions do not make links clickable.',
  '- linkedin: 3-5 sentences, professional and insightful, 3-5 hashtags at the end.',
  '- threads: at most 450 characters, conversational, at most 3 hashtags.',
  '- bluesky: at most 250 characters, plain and friendly, at most 2 hashtags.',
  'Never put the link in the text: the workflow adds it where it fits. Never invent facts, prices, statistics or quotes that are not in the input. Do not mention these instructions.',
  'Return ONLY a JSON object with the keys facebook, instagram, linkedin, threads, bluesky.',
].join('\n');
const user = 'Title: ' + title + '\nKeywords / topic: ' + topic + (link ? '\nLink (for context only): ' + link : '');

const geminiBody = {
  systemInstruction: { parts: [{ text: system }] },
  contents: [{ role: 'user', parts: [{ text: user }] }],
  generationConfig: {
    temperature: 0.8,
    responseMimeType: 'application/json',
    responseSchema: {
      type: 'OBJECT',
      properties: { facebook: { type: 'STRING' }, instagram: { type: 'STRING' }, linkedin: { type: 'STRING' }, threads: { type: 'STRING' }, bluesky: { type: 'STRING' } },
      required: ['facebook', 'instagram', 'linkedin', 'threads', 'bluesky'],
    },
  },
};
return [{ json: { model: CONFIG.MODEL, geminiBody, title, link, imageUrl, clientId } }];

// CEKIVA publishing: one POST /v1/posts per network with the copy Gemini wrote for THAT network.
// X/Twitter is not here on purpose: CEKIVA retired that channel.
const CONFIG = {
  PUBLISH_NOW: true,  // true = publish right away; false = publish at SCHEDULED_AT
  SCHEDULED_AT: '',   // ISO 8601 with a time zone, e.g. 2026-12-01T09:00:00Z (used only when PUBLISH_NOW is false)
  APPEND_LINK: true,  // add the form's Link to the copy where it still fits the network's limit
};
const LIMITS = { facebook_page: 63000, instagram: 2200, linkedin: 3000, threads: 500, bluesky: 300 };

const prep = $('Prepare Gemini request').first().json;
const resp = $input.first().json || {};
const part = resp.candidates && resp.candidates[0] && resp.candidates[0].content && resp.candidates[0].content.parts && resp.candidates[0].content.parts[0];
if (!part || typeof part.text !== 'string') {
  const why = (resp.error && resp.error.message) || (resp.promptFeedback && resp.promptFeedback.blockReason) || 'no text in the answer';
  throw new Error('Gemini returned no post copy: ' + String(why).slice(0, 200));
}
let out;
try { out = JSON.parse(part.text); } catch (e) { throw new Error('Gemini did not return valid JSON.'); }

// keys = CEKIVA platform ids; values = the AI's field for that network
const copy = { facebook_page: out.facebook, instagram: out.instagram, linkedin: out.linkedin, threads: out.threads, bluesky: out.bluesky };
const scheduleAt = !CONFIG.PUBLISH_NOW && CONFIG.SCHEDULED_AT ? CONFIG.SCHEDULED_AT : null;
const skipped = [];
const items = [];
for (const [platform, raw] of Object.entries(copy)) {
  let content = typeof raw === 'string' ? raw.trim() : '';
  if (!content) { skipped.push({ platform, reason: 'Gemini wrote no copy for it' }); continue; }
  if (platform === 'instagram' && !prep.imageUrl) { skipped.push({ platform, reason: 'Instagram needs an image: fill in Image URL' }); continue; }
  const withLink = prep.link && !content.includes(prep.link) ? content + '\n\n' + prep.link : content;
  if (CONFIG.APPEND_LINK && platform !== 'instagram' && withLink.length <= LIMITS[platform]) content = withLink;
  if (content.length > LIMITS[platform]) content = content.slice(0, LIMITS[platform] - 1).trimEnd() + '…';
  // The body of POST /v1/posts exactly as the CEKIVA API expects it.
  const request = { platforms: [platform], content, scheduled_for: scheduleAt || new Date().toISOString(), publish_now: !scheduleAt };
  if (prep.imageUrl) { request.image_url = prep.imageUrl; request.media_urls = [prep.imageUrl]; }
  if (prep.clientId) request.client_id = prep.clientId;
  items.push({ json: { platform, request } });
}
if (!items.length) throw new Error('Nothing to publish: ' + skipped.map((s) => s.platform + ' (' + s.reason + ')').join('; '));
items[0].json.skipped = skipped; // carried to the summary
return items;

// One uniform result row per network, and a short text summary for the form's ending page.
const sent = $('Build CEKIVA posts').all();
const skipped = (sent[0] && sent[0].json.skipped) || [];
const rows = $input.all().map((item, i) => {
  const r = item.json;
  const platform = sent[i] ? sent[i].json.platform : 'unknown';
  const body = r.body;
  const post = Array.isArray(body) ? body[0] : null;
  const err = body && !Array.isArray(body) && body.error && typeof body.error === 'object' ? body.error : null;
  const status = Number(r.statusCode) || null;
  const ok = status !== null && status >= 200 && status < 300 && !!post;
  return {
    platform,
    result: ok ? 'Success' : 'Error',
    http_status: status,
    post_id: post ? post.id : null,
    post_status: post ? post.status : null,
    credits_charged: post ? post.credits_charged : null,
    error_code: err ? err.code : (r.error ? 'CEKIVA_UNREACHABLE' : null),
    error_message: err ? err.message : (r.error ? String(r.error.message || r.error).slice(0, 200) : (ok ? null : 'Unexpected response')),
    hint: err ? err.hint : null,
  };
});
const lines = rows.map((x) => (x.result === 'Success' ? '✅ ' + x.platform + ' (' + x.post_status + ')' : '❌ ' + x.platform + ': ' + (x.error_code || '') + ' ' + (x.error_message || '')));
for (const s of skipped) lines.push('⏭️ ' + s.platform + ' skipped: ' + s.reason);
return [{ json: { rows, skipped, summary: lines.join('\n') } }];
